/// A* on any [`TileSource`]. Like [`astar_tile_grid`] but 8-connected:
/// the four orthogonal steps plus the four diagonal ones, all at uniform
/// cost. Diagonal moves are only taken when both adjacent orthogonal
/// tiles are also passable, so a unit of width cannot slip through the
/// corner seam where two walls touch only at a point. `extra_blocked`
/// layers extra impassable cells on top, exactly as in [`astar_tile_grid`].
pub fn astar_tile_grid_8<T: TileSource>(
    src: &T,
    start: (i32, i32),
    goal:  (i32, i32),
    extra_blocked: &HashSet<(i32, i32)>,
) -> Option<Vec<(u16, u16)>> {
    if start == goal { return Some(Vec::new()); }
    if src.blocks(goal.0, goal.1) { return None; }
    let (w, h) = src.dims();
    let heur = |p: (i32, i32)| -> u32 {
        (p.0 - goal.0).unsigned_abs() + (p.1 - goal.1).unsigned_abs()
    };
    let mut open: OpenSet = BinaryHeap::new();
    let mut g_score: HashMap<(i32, i32), u32> = HashMap::new();
    let mut came_from: HashMap<(i32, i32), (i32, i32)> = HashMap::new();
    let mut closed: HashSet<(i32, i32)> = HashSet::new();
    open.push(Reverse((heur(start), 0, start)));
    g_score.insert(start, 0);
    let cap = (w as usize).saturating_mul(h as usize).max(1);
    let mut expanded = 0usize;
    while let Some(Reverse((_f, g, cur))) = open.pop() {
        if cur == goal { return Some(reconstruct(&came_from, cur)); }
        if !closed.insert(cur) { continue; }
        expanded += 1;
        if expanded > cap { return None; }
        for (dx, dy) in [
            (0i32, 1i32), (0, -1), (1, 0), (-1, 0),
            (1, 1), (1, -1), (-1, 1), (-1, -1),
        ] {
            let nb = (cur.0 + dx, cur.1 + dy);
            if src.blocks(nb.0, nb.1) { continue; }
            if extra_blocked.contains(&nb) { continue; }
            if closed.contains(&nb) { continue; }
            // A diagonal step must not wedge a wide unit through the corner
            // seam where two orthogonal walls meet. Require both neighbours
            // along the turn to be passable too.
            if dx != 0 && dy != 0 {
                if src.blocks(cur.0 + dx, cur.1) { continue; }
                if src.blocks(cur.0, cur.1 + dy) { continue; }
            }
            let tentative = g + 1;
            let better = g_score.get(&nb).is_none_or(|&old| tentative < old);
            if !better { continue; }
            g_score.insert(nb, tentative);
            came_from.insert(nb, cur);
            open.push(Reverse((tentative + heur(nb), tentative, nb)));
        }
    }
    None
}","old_str":"    None
