5: /// Type-erased view over a `ComponentStorage<T>` so `despawn` can wipe any
6: /// component slot without knowing T at the call site. Without this, a slot
7: /// reused by a new entity inherits the old occupant's components.
8: // Require `Sync` on component storages so `&World` implements `Sync`
9: // automatically — needed by server-side rayon workloads (per-session
10: // snapshot build fans out to a worker pool with a shared `&World`
11: // reference). All game components are plain `Clone` data structs
12: // already; nothing in the tree stores `Rc<T>` or bare `Cell<T>`, so
13: // the added bound is a compile-time formality.
14: trait AnyStorage: Any + Send + Sync {
15:     fn clear_slot(&mut self, index: usize);
16:     fn as_any(&self) -> &dyn Any;
17:     fn as_any_mut(&mut self) -> &mut dyn Any;
18: }
19: 
20: struct ComponentStorage<T> {
21:     data: Vec<Option<T>>,
22: }
23: 
24: impl<T: Send + Sync + 'static> ComponentStorage<T> {
25:     fn new() -> Self {
26:         Self { data: Vec::new() }
27:     }
28: 
29:     fn insert(&mut self, index: usize, val: T) {
30:         if index >= self.data.len() {
31:             self.data.resize_with(index + 1, || None);
32:         }
33:         self.data[index] = Some(val);
34:     }
35: 
36:     fn get(&self, index: usize) -> Option<&T> {
37:         self.data.get(index)?.as_ref()
38:     }
39: 
40:     fn get_mut(&mut self, index: usize) -> Option<&mut T> {
41:         self.data.get_mut(index)?.as_mut()
42:     }
43: 
44:     fn remove(&mut self, index: usize) {
45:         if index < self.data.len() {
46:             self.data[index] = None;
47:         }
48:     }
49: }
50: 
51: impl<T: Send + Sync + 'static> AnyStorage for ComponentStorage<T> {
52:     fn clear_slot(&mut self, index: usize) {
53:         if index < self.data.len() {
54:             self.data[index] = None;
55:         }
56:     }
57:     fn as_any(&self) -> &dyn Any { self }
58:     fn as_any_mut(&mut self) -> &mut dyn Any { self }
59: }
60: 
61: pub struct World {
62:     generations: Vec<u32>,
63:     free_list: Vec<u32>,
64:     alive: Vec<bool>,
65:     components: HashMap<TypeId, Box<dyn AnyStorage>>,
66: }
67: 
68: impl World {
69:     pub fn new() -> Self {
70:         Self {
71:             generations: Vec::new(),
72:             free_list: Vec::new(),
73:             alive: Vec::new(),
74:             components: HashMap::new(),
75:         }
76:     }
77: 
78:     pub fn spawn(&mut self) -> EntityId {
79:         if let Some(index) = self.free_list.pop() {
80:             let gen = self.generations[index as usize];
81:             self.alive[index as usize] = true;
82:             EntityId { index, generation: gen }
83:         } else {
84:             let index = self.generations.len() as u32;
85:             self.generations.push(0);
86:             self.alive.push(true);
87:             EntityId { index, generation: 0 }
88:         }
89:     }
90: 
91:     pub fn despawn(&mut self, id: EntityId) {
92:         if !self.alive(id) {
93:             return;
94:         }
95:         // Wipe every component slot for this index — otherwise a new entity
96:         // popping this slot off the free list would inherit stale components.
97:         let idx = id.index as usize;
98:         for storage in self.components.values_mut() {
99:             storage.clear_slot(idx);
100:         }
101:         self.generations[idx] += 1;
102:         self.alive[idx] = false;
103:         self.free_list.push(id.index);
104:     }
105: 
106:     pub fn alive(&self, id: EntityId) -> bool {
107:         self.alive
108:             .get(id.index as usize)
109:             .copied()
110:             .unwrap_or(false)
111:             && self.generations.get(id.index as usize).copied() == Some(id.generation)
112:     }
113: 
114:     fn storage<T: Send + Sync + 'static>(&self) -> Option<&ComponentStorage<T>> {
115:         self.components.get(&TypeId::of::<T>())?.as_any().downcast_ref::<ComponentStorage<T>>()
116:     }
117: 
118:     fn storage_mut<T: Send + Sync + 'static>(&mut self) -> &mut ComponentStorage<T> {
119:         self.components
120:             .entry(TypeId::of::<T>())
121:             .or_insert_with(|| Box::new(ComponentStorage::<T>::new()) as Box<dyn AnyStorage>)
122:             .as_any_mut()
123:             .downcast_mut::<ComponentStorage<T>>()
124:             .unwrap()
125:     }
126: 
127:     pub fn insert<T: Send + Sync + 'static>(&mut self, id: EntityId, val: T) {
128:         if !self.alive(id) {
129:             return;
130:         }
131:         self.storage_mut::<T>().insert(id.index as usize, val);
132:     }
133: 
134:     pub fn get<T: Send + Sync + 'static>(&self, id: EntityId) -> Option<&T> {
135:         if !self.alive(id) {
136:             return None;
137:         }
138:         self.storage::<T>()?.get(id.index as usize)
139:     }
140: 
141:     pub fn get_mut<T: Send + Sync + 'static>(&mut self, id: EntityId) -> Option<&mut T> {
142:         if !self.alive(id) {
143:             return None;
144:         }
145:         self.storage_mut::<T>().get_mut(id.index as usize)
146:     }
147: 
148:     pub fn has<T: Send + Sync + 'static>(&self, id: EntityId) -> bool {
149:         self.get::<T>(id).is_some()
150:     }
151: 
152:     pub fn remove<T: Send + Sync + 'static>(&mut self, id: EntityId) {
153:         self.storage_mut::<T>().remove(id.index as usize);
154:     }
155: 
156:     pub fn entities(&self) -> impl Iterator<Item = EntityId> + '_ {
157:         self.alive
158:             .iter()
159:             .enumerate()
160:             .filter(|(_, &a)| a)
161:             .map(move |(i, _)| EntityId {
162:                 index: i as u32,
163:                 generation: self.generations[i],
164:             })
165:     }
166: 
167:     /// Iterate all entities with component T. Single allocation (raw-pointer vec → safe refs).
168:     pub fn iter<T: Send + Sync + 'static>(&self) -> impl Iterator<Item = (EntityId, &T)> {
169:         let pairs: Vec<(EntityId, *const T)> = match self.storage::<T>() {
170:             None => vec![],
171:             Some(storage) => storage
172:                 .data
173:                 .iter()
174:                 .enumerate()
175:                 .filter_map(|(i, slot)| {
176:                     let val = slot.as_ref()?;
177:                     if *self.alive.get(i).unwrap_or(&false) {
178:                         Some((EntityId { index: i as u32, generation: self.generations[i] }, val as *const T))
179:                     } else {
180:                         None
181:                     }
182:                 })
183:                 .collect(),
184:         };
185:         pairs.into_iter().map(|(id, ptr)| (id, unsafe { &*ptr }))
186:     }
187: 
188:     pub fn iter_mut<T: Send + Sync + 'static>(&mut self) -> impl Iterator<Item = (EntityId, &mut T)> {
189:         let alive = &self.alive;
190:         let gens = &self.generations;
191:         let storage = self
192:             .components
193:             .entry(TypeId::of::<T>())
194:             .or_insert_with(|| Box::new(ComponentStorage::<T>::new()) as Box<dyn AnyStorage>)
195:             .as_any_mut()
196:             .downcast_mut::<ComponentStorage<T>>()
197:             .unwrap();
198: 
199:         let pairs: Vec<(EntityId, *mut T)> = storage
200:             .data
201:             .iter_mut()
202:             .enumerate()
203:             .filter_map(|(i, slot)| {
204:                 let val = slot.as_mut()?;
205:                 if *alive.get(i).unwrap_or(&false) {
206:                     Some((EntityId { index: i as u32, generation: gens[i] }, val as *mut T))
207:                 } else {
208:                     None
209:                 }
210:             })
211:             .collect();
212: 
213:         pairs.into_iter().map(|(id, ptr)| (id, unsafe { &mut *ptr }))
214:     }
215: 
216:     /// Iterate entities that have both A and B. Walks A's storage, O(1) lookup into B.
217:     /// Eliminates the collect-then-double-get pattern: one pass, two components.
218:     pub fn iter2<A: Send + Sync + 'static, B: Send + Sync + 'static>(&self) -> impl Iterator<Item = (EntityId, &A, &B)> {
219:         let pairs: Vec<(EntityId, *const A, *const B)> = match (self.storage::<A>(), self.storage::<B>()) {
220:             (Some(sa), Some(sb)) => sa
221:                 .data
222:                 .iter()
223:                 .enumerate()
224:                 .filter_map(|(i, slot_a)| {
225:                     let a = slot_a.as_ref()?;
226:                     if !self.alive.get(i).copied().unwrap_or(false) {
227:                         return None;
228:                     }
229:                     let b = sb.get(i)?;
230:                     Some((
231:                         EntityId { index: i as u32, generation: self.generations[i] },
232:                         a as *const A,
233:                         b as *const B,
234:                     ))
235:                 })
236:                 .collect(),
237:             _ => vec![],
238:         };
239:         pairs.into_iter().map(|(id, pa, pb)| (id, unsafe { &*pa }, unsafe { &*pb }))
240:     }
241: }
