//! Word-wraps a source line to a column width, for the narrow terminal view.

#[path = "highlight.rs"]
pub mod highlight;

use highlight::span::{chunk_count, line_span};

/// Wrap the line containing `at` into chunks of at most `width` bytes.
///
/// The line is taken by span, so this never allocates the whole file.
pub fn wrap_line(text: &str, at: usize, width: usize) -> Vec<String> {
    let s = line_span(text, at);
    let line = &text[s.start..s.end];
    let n = chunk_count(line.len(), width);
    let mut out = Vec::with_capacity(n);
    for k in 0..n {
        let i = (k * width).min(line.len());
        let j = (i + width).min(line.len());
        out.push(line[i..j].to_string());
    }
    out
}
//! Byte-span arithmetic shared by everything that slices source text.

/// A half-open byte span `[start, end)` into some source string.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Span {
    pub start: usize,
    pub end: usize,
}

impl Span {
    pub fn new(start: usize, end: usize) -> Self {
        Span { start, end }
    }

    /// The number of bytes this span covers.
    pub fn len(&self) -> usize {
        self.end - self.start
    }
}

/// The span of the line containing byte offset `at`, excluding the newline that
/// ends it.
pub fn line_span(text: &str, at: usize) -> Span {
    let start = text[..at].rfind('\n').map(|i| i + 1).unwrap_or(0);
    let end = match text[at..].find('\n') {
        Some(i) => at + i,
        None => text.len(),
    };
    Span::new(start, end)
}

/// How many chunks of at most `width` bytes it takes to cover `len` bytes.
///
/// A zero-length input still needs one (empty) chunk, so callers always have
/// something to render.
pub fn chunk_count(len: usize, width: usize) -> usize {
    if width == 0 {
        return 1;
    }
    len / width + 1
}

